Lemma dof_shvis_transport_awin : forall W m m' a b,
  shvis m a b -> munch W m m' -> wmono asegs m m' -> Forall awin W -> 0 <= a <= b -> b <= AAPP_HI -> shvis m' a b.
Proof.
  intros W m m' a b SV MU WM FW H0 Hb. eapply shvis_transport; [exact SV| exact MU| exact WM|].
  pose proof (hull_lo_le a ltac:(lia)) as (L1 & L2 & L3). pose proof (hull_hi_ge b ltac:(lia)) as (G1 & G2 & G3).
  assert (LE : hull_hi b <= AAPP_HI) by (unfold AAPP_HI in *; Z.div_mod_to_equations; nia).
  pose proof (sh_mono _ _ LE) as KM. pose proof (sh_ge_lowsh (hull_lo a) ltac:(lia)) as KL.
  apply awin_disjoint_shland; [exact FW| exact KL|].
  unfold sh, AAPP_HI, AHI_LO in *. rewrite ASHADOW_BASE_val in *. change (2147450880 + 2 ^ 47 / 8) with 17594333495296 in KM. lia.
Qed.

